                factoringFee: factoringFee,
                creditInterest: creditInterest,
                financingCost: periodFinancingCost,
                netCashFlow: Math.round(netCashFlow),
                cash: ds.cash,
                ccc: ds.ccc,
                dso: ds.dso,
                dio: ds.dio,
                dpo: ds.dpo,
                currentRatio: currentRatio,
                supplierRelationship: ds.supplierRelationship,
                customerRelationship: ds.customerRelationship,
                fillRate: fillRate,
                creditAvailable: creditLimit - ds.creditLineUsed
            };
        }

