        getHint(state, results) {
            if (!results) return null;
            if (results.cash < 0) return window.mySimulation.t('hint_cash_negative');
            if (results.cash < 500) return window.mySimulation.t('hint_cash_low');
            if (results.ccc > 55) return window.mySimulation.t('hint_ccc_high');
            if (results.currentRatio < 1.15) return window.mySimulation.t('hint_covenant');
            if (results.supplierRelationship < 50) return window.mySimulation.t('hint_supplier_risk');
            if (state.decisions.factoringPct > 50) return window.mySimulation.t('hint_factoring_expensive');
            if (results.profit > 0 && results.ccc < 40) return window.mySimulation.t('hint_good');
            return null;
        }

